/// <summary>
/// <c>METPickupAdviceReportDP</c> class holds the logic to run the pickup advice report
/// </summary>
[SrsReportParameterAttribute(classStr(METPickupAdviceReportContract))]
public class METPickupAdviceReportDP extends SrsReportDataProviderPreProcessTempDB
{
    METPickupAdviceReportHeaderTmp      headerTableTmp;
    METPickupAdviceReportLineTmp        lineTableTmp;
    RecordInsertList                    headerTableList;
    RecordInsertList                    lineTableList;
    METPickupAdviceReportContract       contract;
    METBundleGuid         bundleHeaderReportGuid;
    METBundleGuid         headerReportGuid;

}

Method.Source:
/// <summary>
/// Set the bundling guid values to the tmp tables
/// </summary>
/// <param name = "_bundleHeaderReportGuid">Bundle header report guid</param>
/// <param name = "_headerReportGuid">Header report guid</param>
public void setBundlingGuid(METBundleGuid     _bundleHeaderReportGuid, METBundleGuid    _headerReportGuid)
{
    bundleHeaderReportGuid = _bundleHeaderReportGuid;
    headerReportGuid = _headerReportGuid;
}

/// <summary>
/// method to get data of table METPickupAdviceReportHeaderTmp
/// </summary>
/// <returns>METPickupAdviceReportHeaderTmp</returns>
[SrsReportDataSetAttribute('METPickupAdviceReportHeaderTmp')]
public METPickupAdviceReportHeaderTmp getHeaderData()
{
    select * from headerTableTmp;
    return headerTableTmp;
}

/// <summary>
/// method to get data of table METPickupAdviceReportLineTmp
/// </summary>
/// <returns>METPickupAdviceReportLineTmp</returns>
[SrsReportDataSetAttribute('METPickupAdviceReportLineTmp')]
public METPickupAdviceReportLineTmp getLineData()
{
    select * from lineTableTmp;
    return lineTableTmp;
}

/// <summary>
/// Logic to run the report
/// </summary>
public void processReport()
{

    METSalesOrderShipmentLoadLines      soShipmentLines;
    SalesTable                          salesTable;

    contract = this.parmDataContract();

    SalesReturnItemNum      rmaNumber   = contract.parmRMANumber();

    headerTableList = new RecordInsertList(tableNum(METPickupAdviceReportHeaderTmp), true, true, true, true, true, headerTableTmp);

    select salesTable
        where salesTable.ReturnItemNum == rmaNumber;

    if (salesTable.ReturnItemNum)
    {
        headerTableTmp.clear();

        InventLocation                      inventLocationShip  = InventLocation::find(salesTable.InventLocationId);
        METIndustryKeyTable                 industryKey         = METIndustryKeyTable::find(inventLocationShip.METWHSubEntity);
        SysDocuBrandDetails                 docuBrandingDetails = this.getDocuBrandingDetails(inventLocationShip.METWHSubEntity);
        CustTable                           custTable           = CustTable::find(salesTable.CustAccount);
        LogisticsPostalAddress              dlvAddress          = this.getCustDlvAddress(custTable.party, LogisticsLocationRoleType::Delivery);
        METSalesTable                       metSalesTable       = METSalesTable::findByRefRecId(salesTable.RecId);

        if (salesTable.SalesType == SalesType::ReturnItem)
        {
            headerTableTmp.Logo =   SysDocuBrandImages::getImage(inventLocationShip.METWHSubEntity);
        }

        //headerTableTmp.Logo                 = SysDocuBrandImages::getImage(inventLocationSO.METWHSubEntity);// task 226482
        headerTableTmp.IndustryKey          = industryKey.IndustryKey; //task 218182
        headerTableTmp.CompanyName          = industryKey.CompanyName;
        headerTableTmp.ABN                  = METIndustryKeyTable::find(inventLocationShip.METWHSubEntity).CoRegNum;
        headerTableTmp.WarehouseName        = inventLocationShip.Name;
        headerTableTmp.WarehouseAddress     = inventLocationShip.address();
        headerTableTmp.Phone                = docuBrandingDetails.phone;
        headerTableTmp.PickupFromName       = custTable.name();
        headerTableTmp.PickupFromAddress    = dlvAddress.Address;
        headerTableTmp.PickupInstruction    = '';
        headerTableTmp.RMA                  = salesTable.ReturnItemNum;
        headerTableTmp.SalesId              = salesTable.SalesId;
        headerTableTmp.CustAccount          = custTable.AccountNum;
        headerTableTmp.InvoiceId            = metSalesTable.OriginalInvoice;
        headerTableTmp.InvoiceDate          = this.getInvoiceDate(metSalesTable.OriginalInvoice);
        headerTableTmp.ClaimNo              = metSalesTable.ParentClaimId;
        headerTableTmp.ClaimDate            = DateTimeUtil::date(salesTable.CreatedDateTime);
        headerTableTmp.Reason               = strFmt("@MET:METAMEXJournalName",salesTable.ReturnReasonCodeId, ReturnReasonCode::find(salesTable.ReturnReasonCodeId).Description);
        headerTableTmp.BundleReportHeaderGuidStr = bundleHeaderReportGuid;
        headerTableTmp.PickupAdviceHeaderGuidStr = headerReportGuid;

        headerTableList.add(headerTableTmp);

        this.initializeLine(salesTable.SalesId,salesTable.ReturnItemNum, headerTableTmp);
    }
    headerTableList.insertDatabase();
}

/// <summary>
/// method to initialize the line table
/// </summary>
/// <param name = "_salesID">SalesId</param>
protected void initializeLine(SalesId   _salesID, SalesReturnItemNum   _returnItemNum, METPickupAdviceReportHeaderTmp  _headerTmp)
{
    SalesLine           salesLineLoc;

    lineTableList = new RecordInsertList(tableNum(METPickupAdviceReportLineTmp), true, true, true, true, true, lineTableTmp);

    while select ItemId, SalesUnit, ExpectedRetQty, InventDimId, ReturnDispositionCodeId from salesLineLoc
        where salesLineLoc.SalesId == _salesId
    {
        InventTable     inventTableloc  = InventTable::find(salesLineLoc.ItemId);

        lineTableTmp.clear();

        lineTableTmp.RMA                = _returnItemNum;
        lineTableTmp.SalesId            = _salesID;
        lineTableTmp.ItemId             = salesLineLoc.ItemId;
        lineTableTmp.ItemDescription    = EcoResProductTranslation::findByProductLanguage(inventTableloc.Product,SystemParameters::getSystemLanguageId()).Description;
        lineTableTmp.UOM                = salesLineLoc.SalesUnit;
        lineTableTmp.Qty                = abs(salesLineLoc.ExpectedRetQty);
        lineTableTmp.PackQuantity       = abs(this.getSaleUnitQty(salesLineLoc.ExpectedRetQty, inventTableloc.ItemId, salesLineLoc.SalesUnit, METConstants::unitEach));
        lineTableTmp.SlotNo             = this.getSlotNo(salesLineLoc.ItemId, salesLineLoc.InventDimId);
        lineTableTmp.DispositionCode    = salesLineLoc.ReturnDispositionCodeId;

        lineTableTmp.BundleReportHeaderGuidStr = bundleHeaderReportGuid;
        lineTableTmp.PickupAdviceHeaderGuidStr = headerReportGuid;
        lineTableList.add(lineTableTmp);
    }

    lineTableList.insertDatabase();
}

protected LogisticsPostalAddress getCustDlvAddress(DirPartyRecId _party, LogisticsLocationRoleType _type)
{
    DirPartyLocation        partyLocation;
    DirPartyLocationRole    partyLocationRole;
    LogisticsLocationRole   locationRole;
    LogisticsPostalAddress  postalAddress;

    select firstonly postalAddress
        exists join locationRole
            where locationRole.Type  == _type
            exists join partyLocation
                where partyLocation.Location == postalAddress.Location &&
                    partyLocation.Party == _party
                exists join partyLocationRole
                    where partyLocationRole.PartyLocation == partyLocation.RecId &&
                        partyLocationRole.LocationRole == locationRole.RecId;

    return postalAddress;
}

protected SysDocuBrandDetails getDocuBrandingDetails(METIndustryKey _industryKey)
{
    SysDocuBrandDetails     docuBrandingDetails;

    //logic to get brand details based on the report name - task 237151 ----------------->
    select firstonly docuBrandingDetails
        where docuBrandingDetails.METIndustryKey == _industryKey &&
        docuBrandingDetails.ReportName == METConstants::PickupAdvice;   //Bug 237151
    //logic to get brand details based on the report name - task 237151 ----------------->

    //docuBrandingDetails = SysDocuBrandDetails::findBrandDocument(_industryKey,METConstants::PickupAdvice,ssrsReportStr(METPickUpAdvicesReport, Report));

    return docuBrandingDetails;
}

protected InvoiceDate getInvoiceDate(InvoiceId _invoiceId)
{
    CustInvoiceJour     invoiceJour;

    select firstonly InvoiceDate from invoiceJour
        where invoiceJour.InvoiceId == _invoiceId;

    return invoiceJour.InvoiceDate;
}

protected Qty getSaleUnitQty(Qty _qty, ItemId _itemId,SalesUnit _inventUnit,SalesUnit _salesUnit)
{
    Qty     salesQty;

    salesQty = UnitOfMeasureConverter::convert(_qty,
           UnitOfMeasure::unitOfMeasureIdBySymbol(_inventUnit),
           UnitOfMeasure::unitOfMeasureIdBySymbol(_salesUnit),
           NoYes::Yes,
           InventTable::itemProduct(_itemId),
           NoYes::Yes);

    return salesQty;
}

protected METSlotLoc1Area getSlotNo(ItemId _itemId, InventDimId _inventDimId)
{
    InventDim           inventDim       = InventDim::find(_inventDimId);
    InventDim           covInventDim;
    ReqItemTable        reqItemTable;

    covInventDim.InventSiteId       = inventDim.InventSiteId;
    covInventDim.InventLocationId   = inventDim.InventLocationId;

    covInventDim    = InventDim::findOrCreate(covInventDim);

    reqItemTable    = ReqItemTable::find(_itemId, covInventDim.inventDimId);

    return METReqItemTable::find(reqItemTable.RecId).SlotLoc1Area;
}
